 const tunnelT=.42,q=getPoint(tunnelT),v=getTangent(tunnelT),tunnel=new THREE.Group();tunnel.position.copy(q);tunnel.rotation.y=Math.atan2(v.x,v.z);for(let i=0;i<4;i++){for(const x of [-18,18])box(1.2,13,1.2,0x6ca7bd,tunnel,x,6.5,(i-1.5)*7);box(37,1.2,1.2,[0xf8b871,0xa6a1df,0x8bcecb,0xd2e58a][i],tunnel,0,13,(i-1.5)*7);}scene.add(tunnel);
