function resetPlayer(t=.01){const p=getPoint(t),v=getTangent(t);Object.assign(player,{x:p.x,z:p.z,angle:Math.atan2(v.x,v.z),speed:0,t,energy:100,boostUntil:0,progress:0,lastT:t});kart.position.set(p.x,.9,p.z);kart.rotation.y=player.angle;}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let boardRequest=0;
async function api(path,body){const r=await fetch(API_URL+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok)throw Error(data.error||'The record board is unavailable. Please try again.');return data;}
async function refreshBoard(){const request=++boardRequest;$('#leaderboard').textContent='Loading race records…';try{const {scores}=await api('/scores');if(request!==boardRequest)return;$('#leaderboard').innerHTML=scores.length?scores.map((s,i)=>`<div class="board-row"><b>${i+1}</b><span title="${escapeHTML(s.name)}">${escapeHTML(s.name)}</span><time>${timeString(s.milliseconds/1000)}</time></div>`).join(''):'<p class="board-empty">No records yet.<br>Your name could be first on the grid.</p>';}catch{if(request===boardRequest)$('#leaderboard').innerHTML='<p class="board-empty">The board is taking a pit stop.<br>Tap Refresh to reconnect.</p>';}}
$('#refresh-board').onclick=refreshBoard;void refreshBoard();
let visitorId;try{visitorId=localStorage.getItem('rudra-review-id');}catch{}if(!/^[a-f0-9]{32}$/.test(visitorId||'')){visitorId=crypto.randomUUID().replaceAll('-','');try{localStorage.setItem('rudra-review-id',visitorId);}catch{}}
async function refreshRating(){try{const r=await api('/reviews/summary');document.querySelectorAll('[data-rating-summary]').forEach(el=>el.textContent=r.count?r.average.toFixed(1)+' / 5 · '+r.count+' REVIEW'+(r.count===1?'':'S'):'BE THE FIRST TO RATE THE RIDE');}catch{document.querySelectorAll('[data-rating-summary]').forEach(el=>el.textContent='RATE YOUR DRIVE');}}
function reviewRide(initial=0){let rating=initial;showPanel('How was the ride?','VISITOR FEEDBACK / THANKS FOR DROPPING BY',`<p>Rate the portfolio from 1 to 5 stars. Got an idea, spotted a bug, or enjoyed a particular stop? Leave an optional note.</p><form id="review-form"><div class="review-stars" role="group" aria-label="Choose your rating">${[1,2,3,4,5].map(n=>`<button type="button" data-review-star="${n}" aria-label="${n} stars" aria-pressed="${n<=rating}">★</button>`).join('')}</div><p id="chosen-rating">${rating?rating+' out of 5':'Choose a star rating'}</p><label for="review-comment">Your review (optional, private)</label><textarea id="review-comment" maxlength="1000" rows="4" placeholder="What worked? What could be better?"></textarea><p class="fine">Only Rudra can read your comment. Your star rating contributes to the public average and review count. One review per browser.</p><div class="resume-actions"><button class="primary" id="send-review">SEND REVIEW →</button><button type="button" class="secondary" id="cancel-review">CANCEL</button></div><p id="review-status" role="status"></p></form>`);panel.querySelectorAll('[data-review-star]').forEach(b=>b.onclick=()=>{rating=+b.dataset.reviewStar;panel.querySelectorAll('[data-review-star]').forEach(x=>x.setAttribute('aria-pressed',String(+x.dataset.reviewStar<=rating)));$('#chosen-rating').textContent=rating+' out of 5';});$('#cancel-review').onclick=closePanel;$('#review-form').onsubmit=async e=>{e.preventDefault();if(!rating){$('#review-status').textContent='Choose a star rating first.';return;}$('#send-review').disabled=true;try{await api('/reviews',{rating,comment:$('#review-comment').value,visitor:visitorId});$('#panel-content').innerHTML='<h3>Thanks for the feedback!</h3><p>Your rating is counted, and your note is saved privately for Rudra.</p>';refreshRating();}catch(err){$('#review-status').textContent=err.message;$('#send-review').disabled=false;}};}
document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>reviewRide(+b.dataset.rating));$('#review-link').onclick=()=>reviewRide();void refreshRating();

function beginIntro(tour){if(musicPreference!==false)void setSound(true);showPanel('Before we hit the track.','YOUR DRIVER / RUDRA MAHARAO',`<div class="driver-card"><img src="assets/rudra.jpg" alt="Rudra Maharao"><div><h3>Hi, I’m Rudra.</h3><p>I build applied AI and data systems—and I like a good game.</p></div></div><div class="intro-profile-grid"><article><span>01 / ACADEMICS</span><h3>B.Tech Data Science</h3><p>NMIMS MPSTME, Mumbai<br>Expected 2028 · CGPA <b>8.11</b></p></article><article><span>02 / EXPERIENCE</span><h3>Testing & teaching</h3><p><b>WeTest, May–July 2026:</b> reported 20+ gameplay, controls and UX bugs.<br><b>Anubhavi Foundation, June–July 2025:</b> tutored eight Grade 10 students in maths.</p></article></div><div class="research-card"><span class="tiny">03 / CERTIFICATIONS</span><ul><li>MongoDB Certified Database Administrator</li><li>RAG Systems & Agentic Workflows with Pinecone and LangGraph — Board Infinity / Coursera</li><li>Neural Networks and Deep Learning — DeepLearning.AI / Andrew Ng</li><li>Improving Deep Neural Networks — DeepLearning.AI / Andrew Ng</li></ul></div><p><b>Your route:</b> two laps, four rivals, and four real projects. Lap one pauses at each project checkpoint. Lap two is uninterrupted. Coins add 100 points each; the leaderboard rewards the quickest time.</p><div class="race-brief"><span>↑ / W ACCELERATE</span><span>← → / A D STEER</span><span>SPACE BOOST</span><span>SHIFT DRIFT</span><span>Q USE ITEM</span></div><p class="fine">${tour?'Scenic Tour steers for you. Boost and items are still yours to use.':'Drive yourself, or switch to cruise control during the race. Every completed run can join the same top-five leaderboard.'} Reading time is excluded from your race time.</p><button class="primary" id="intro-go">${tour?'BEGIN SCENIC TOUR':'LET’S RACE'} →</button><p id="start-status" role="status"></p>`);$('#resume').textContent='START THE RACE →';$('#resume').onclick=()=>startRace(tour);$('#intro-go').onclick=()=>startRace(tour);}
async function startRace(tour){if(!initialized){openSection('projects');return;}const go=$('#intro-go');if(go)go.disabled=true;$('#resume').disabled=true;try{const run=await api('/runs/start',{tour});runToken=run.token;raceState=createRace(run.seed,tour);player=raceState.player;raceLog=[];lastMask=-1;raceAccumulator=0;pulseInput=0;clearControls();collected.clear();visited.clear();pickups.forEach(p=>p.g.visible=true);running=true;paused=false;finished=false;cruising=tour;assisted=tour;elapsed=0;countdownUntil=performance.now()+3000;$('#resume').onclick=closePanel;if(panel.open)panel.close();if($('#record-dialog').open)$('#record-dialog').close();['intro','intro-bottom','world-label','home-board'].forEach(id=>$('#'+id).hidden=true);['race-hud','drive-ui','touch-controls','item-slot'].forEach(id=>$('#'+id).hidden=false);document.body.classList.add('playing');$('#race-mode').textContent=tour?'SCENIC TOUR':'CURIOSITY GP';$('#autodrive').setAttribute('aria-pressed',String(cruising));$('#autodrive b').textContent=cruising?'ON':'OFF';$('#coin-count').textContent='0000';$('#coins-total').textContent='0 COINS';$('#lap').textContent='1 / 2';$('#timer').textContent=timeString(0);$('#countdown').hidden=false;$('#countdown').textContent='3';kart.position.set(player.x,.94,player.z);kart.rotation.y=player.angle;camera.position.copy(kart.position).add(new THREE.Vector3(-Math.sin(player.angle)*25,15,-Math.cos(player.angle)*25));rivals.forEach((r,i)=>{const state=raceState.rivals[i],p=getPoint(state.t),v=getTangent(state.t);r.kart.position.set(p.x-v.z*state.lane,.94,p.z+v.x*state.lane);r.kart.rotation.y=Math.atan2(v.x,v.z);});if(musicPreference!==false)void setSound(true);notify(tour?'Scenic Tour: enjoy the projects, play with items!':'Two laps. Four rivals. Let’s make a good story.',4);}catch(e){const status=$('#start-status');if(status)status.textContent='Could not open a timed run. '+e.message;else notify(e.message,5);}finally{if(go)go.disabled=false;$('#resume').disabled=false;}}
$('#start').onclick=()=>beginIntro(false);$('#tour').onclick=()=>beginIntro(true);
function goHome(){if(panel.open)panel.close();if($('#record-dialog').open)$('#record-dialog').close();running=false;paused=false;finished=false;clearControls();runToken=null;raceLog=[];document.body.classList.remove('playing');['race-hud','drive-ui','touch-controls','checkpoint-prompt','countdown','item-slot'].forEach(id=>$('#'+id).hidden=true);['intro','intro-bottom','world-label','home-board'].forEach(id=>$('#'+id).hidden=false);if(initialized)resetPlayer();$('#resume').onclick=closePanel;refreshBoard();}
$('#home').onclick=goHome;
$('#autodrive').onclick=()=>{pulseInput|=INPUT.CRUISE;};
$('#use-item').onclick=()=>{pulseInput|=INPUT.ITEM;};
$('#explore-stop').onclick=()=>{if(nextStop)openProject(nextStop.id);};
function recover(){if(running)pulseInput|=INPUT.RECOVER;}
window.addEventListener('keydown',event=>{if(panel.open||$('#record-dialog').open||!running||finished)return;const key=event.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','w','a','s','d','shift'].includes(key)){event.preventDefault();keys.add(key);}if(event.repeat)return;if(key==='r')recover();if(key==='q')pulseInput|=INPUT.ITEM;if(key==='e'&&nextStop)openProject(nextStop.id);if(key==='p'||key==='escape')pauseRace();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{clearControls();if(running&&!paused&&!finished)pauseRace();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearControls();if(running&&!paused&&!finished)pauseRace();}});
document.querySelectorAll('[data-control]').forEach(b=>{const c=b.dataset.control;b.addEventListener('pointerdown',e=>{e.preventDefault();controls[c]=true;b.classList.add('pressed');b.setPointerCapture(e.pointerId);});const release=()=>{controls[c]=false;b.classList.remove('pressed');};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);});
function timeString(t){const min=Math.floor(t/60),sec=Math.floor(t%60),dec=Math.floor(t*100)%100;return `${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(dec).padStart(2,'0')}`;}
function afterRaceOptions(saved=false){$('#record-content').innerHTML=`<h2 id="record-title">${saved?'Your name is on the board.':'Thanks for taking the detour.'}</h2><p>${saved?'Your verified time has been saved.':'This run has not been published.'} Ready for another lap around my world?</p><div class="resume-actions"><button class="primary" id="play-again">PLAY AGAIN ↺</button><button class="secondary" id="back-home">HOME PAGE →</button></div>`;$('#play-again').onclick=()=>{$('#record-dialog').close();beginIntro(false);};$('#back-home').onclick=goHome;$('#play-again').focus();}
$('#record-dialog').addEventListener('cancel',e=>{e.preventDefault();if($('#record-form'))afterRaceOptions(false);else goHome();});
function finishRace(){finished=true;player.speed=0;paused=true;clearControls();const rank=1+raceState.rivals.filter(r=>r.progress>player.progress).length;const suffix=n=>n===1?'ST':n===2?'ND':n===3?'RD':'TH';$('#checkpoint-prompt').hidden=true;$('#record-content').innerHTML=`<div class="race-result"><div class="trophy">🏆</div><h2 id="record-title">THAT’S A FINISH!</h2><div class="stat-grid"><div><b>${rank}${suffix(rank)}</b><span>FINISH POSITION</span></div><div><b>${timeString(elapsed)}</b><span>TWO-LAP TIME</span></div><div><b>${raceState.score}</b><span>COIN POINTS</span></div></div><p>${raceState.coins} coins · ${raceState.jumps} ramp jumps · ${raceState.checkpoints.length} projects explored</p><p class="fine">Global leaderboard. Your reading and pause time are excluded.</p><form id="record-form"><label for="record-name">Save your time with a public name or arcade alias</label><input id="record-name" minlength="2" maxlength="20" required autocomplete="off" placeholder="Your name"><div class="record-actions"><button class="primary" id="submit-record">SAVE MY RECORD →</button><button type="button" class="secondary" id="dont-save">DON’T SAVE</button></div><p id="record-status" role="status">Only your name, time and coin score will appear publicly.</p></form></div>`;$('#record-dialog').showModal();$('#record-name').focus();$('#dont-save').onclick=()=>afterRaceOptions(false);let receipt=null;$('#record-form').onsubmit=async e=>{e.preventDefault();const name=$('#record-name').value.trim(),button=$('#submit-record');if(!/^[\p{L}\p{N} _.-]{2,20}$/u.test(name)){$('#record-status').textContent='Use 2–20 letters, numbers, spaces, dots or dashes.';return;}button.disabled=true;$('#record-status').textContent='Verifying your two-lap run…';try{if(!receipt){const verified=await api('/runs/finish',{token:runToken,log:raceLog,endTick:raceState.tick});receipt=verified.receipt;}await api('/scores',{receipt,name});refreshBoard();afterRaceOptions(true);}catch(err){if($('#record-status'))$('#record-status').textContent=err.message;if($('#submit-record'))$('#submit-record').disabled=false;}};chirp();}
function update(dt,now){if(!running||paused||finished)return;if(now<countdownUntil){$('#countdown').textContent=String(Math.ceil((countdownUntil-now)/1000));return;}$('#countdown').hidden=true;raceAccumulator+=dt;let n=0;
 while(raceAccumulator>=DT&&n++<15&&!paused&&!finished){let mask=pulseInput;pulseInput=0;if(keys.has('w')||keys.has('arrowup')||controls.forward)mask|=1;if(keys.has('s')||keys.has('arrowdown')||controls.brake)mask|=2;if(keys.has('a')||keys.has('arrowleft')||controls.left)mask|=4;if(keys.has('d')||keys.has('arrowright')||controls.right)mask|=8;if(keys.has(' ')||controls.boost)mask|=16;if(keys.has('shift')||controls.drift)mask|=64;if(mask!==lastMask){raceLog.push([raceState.tick,mask]);lastMask=mask;}stepRace(raceState,mask);raceAccumulator-=DT;elapsed=raceState.tick*DT;cruising=raceState.cruising;assisted=raceState.assisted;
 for(const e of raceState.events){if(e.type==='coin'){collected.add(e.index%8);notify('+100 POINTS · '+skillNames[e.index%8],1.5);chirp();}if(e.type==='pickup'){notify((e.kept?'ITEM SLOT FULL · KEPT ':'ITEM FOUND: ')+{boost:'TURBO BURST',shield:'BUBBLE SHIELD',pulse:'RIVAL PULSE'}[e.item]+' · Q to use');chirp();}if(e.type==='item')notify({boost:'TURBO BURST! Four seconds of extra speed.',shield:'BUBBLE SHIELD! Protected for 10 seconds.',pulse:'RIVAL PULSE! Chasing the nearest kart.'}[e.item]);if(e.type==='pulse-hit')notify('DIRECT HIT! Rival slowed.');if(e.type==='boost')notify('RAINBOW BOOST!',1.5);if(e.type==='drift')notify('DRIFT RELEASE! Mini-turbo!',1.5);if(e.type==='jump')notify('AIR TIME!',1);if(e.type==='landing')notify('CLEAN LANDING · '+e.combo+'× JUMP COMBO · BOOST!',2);if(e.type==='collision')notify('BUMP! Solid object · steer away or reverse.',1.5);if(e.type==='hazard')notify('BUMPER HIT! Shake it off.',1.5);if(e.type==='blocked')notify('SHIELD SAVED YOU!',1.5);if(e.type==='rival-pulse')notify('RIVAL PULSE! Briefly slowed.',1.5);if(e.type==='recover')notify('Back on track.');if(e.type==='cruise'){notify(e.on?'Cruise control on · this run joins the global leaderboard.':'You’re driving again.');$('#autodrive').setAttribute('aria-pressed',String(e.on));$('#autodrive b').textContent=e.on?'ON':'OFF';}if(e.type==='checkpoint'){const m=projectMeta[e.index];openProject(m.id);$('#resume').textContent='CONTINUE RACE →';$('#panel-eyebrow').textContent=`CHECKPOINT ${e.index+1} / 4 · LAP ONE · TIMER PAUSED`;raceAccumulator=0;}if(e.type==='lap')notify('FINAL LAP! No more stops. Make it count.',4);if(e.type==='finish')finishRace();}
 if(raceState.tick>=71500&&!finished){showPanel('Time for a fresh start.','RUN LIMIT / 20 MINUTES',`<p>Let’s start a new two-lap adventure.</p><button class="primary" id="race-again">PLAY AGAIN →</button>`);finished=true;$('#race-again').onclick=()=>beginIntro(false);}
 }
 const boosted=raceState.tick<player.boostUntil||(keys.has(' ')&&player.energy>1);const floor=rampSurface(player.x,player.z);let slope=0;if(floor.index>=0){const q=point(RAMP_T[floor.index]);slope=-Math.atan2(RAMP.height,RAMP.end-RAMP.start)*(Math.sin(player.angle)*q.vx+Math.cos(player.angle)*q.vz);}kart.position.set(player.x,.94+player.y,player.z);kart.rotation.y=player.angle;kart.rotation.x=player.airborne?Math.max(-.25,Math.min(.25,-player.vy*.012)):slope;kart.rotation.z=THREE.MathUtils.damp(kart.rotation.z,player.drift?Math.sin(clockTime*12)*.12:player.hit?Math.sin(clockTime*30)*.2:0,8,dt);
 for(const [i,r] of rivals.entries()){const state=raceState.rivals[i],v=getTangent(state.t);r.t=state.t;r.progress=state.progress;r.kart.position.set(state.x??getPoint(state.t).x,.94+state.y,state.z??getPoint(state.t).z);r.kart.rotation.y=Math.atan2(v.x,v.z);r.kart.rotation.x=state.airborne?Math.max(-.25,Math.min(.25,-state.vy*.012)):rampSurface(state.x??0,state.z??0).index>=0?-.265:0;}
 const lap=Math.max(0,Math.floor(player.progress+.01));pickups.forEach((item,i)=>item.g.visible=raceState.coinLaps[i]!==lap);itemBoxes.forEach((item,i)=>{item.g.visible=raceState.tick>raceState.boxReady[i];const age=420-(raceState.boxReady[i]-raceState.tick);item.burst.visible=raceState.boxReady[i]>0&&age>=0&&age<30;if(item.burst.visible)item.burst.children.forEach((shard,j)=>{const a=j/8*Math.PI*2,d=age*.15;shard.position.set(Math.cos(a)*d,Math.sin(age/30*Math.PI)*2,Math.sin(a)*d);shard.rotation.set(age*.1,j,age*.15);shard.scale.setScalar(1-age/30);});});hazards.forEach((item,i)=>{const p=getPoint(item.t),v=getTangent(item.t),offset=Math.sin(raceState.tick*.017+i)*11;item.g.position.set(p.x-v.z*offset,.8,p.z+v.x*offset);});shieldMesh.visible=raceState.tick<player.shieldUntil;shieldMesh.position.set(player.x,3+player.y,player.z);shieldMesh.rotation.y=clockTime;for(let i=0;i<pulseMeshes.length;i++){const shot=raceState.projectiles[i];pulseMeshes[i].visible=!!shot;if(shot)pulseMeshes[i].position.set(shot.x,2.8,shot.z);}
 nextStop=null;$('#checkpoint-prompt').hidden=true;const rank=1+rivals.filter(r=>r.progress>player.progress).length;$('#position').textContent=rank;$('#position-suffix').textContent=rank===1?'ST':rank===2?'ND':rank===3?'RD':'TH';$('#speed').textContent=Math.round(Math.abs(player.speed)*3);$('#timer').textContent=timeString(elapsed);$('#lap').textContent=raceState.lap+' / 2';$('#coin-count').textContent=String(raceState.score).padStart(4,'0');$('#coins-total').textContent=raceState.coins+' COINS';$('#boost-fill').style.width=player.energy+'%';$('#boost-label').textContent=player.drift>35?'DRIFT CHARGED · RELEASE SHIFT':boosted?'BOOSTING!':player.energy<20?'RECHARGING…':'BOOST READY · SPACE';$('#item-icon').textContent={boost:'ϟ',shield:'◎',pulse:'✦'}[player.item]||'?';$('#item-name').textContent={boost:'TURBO BURST',shield:'BUBBLE SHIELD',pulse:'RIVAL PULSE'}[player.item]||'FIND AN ITEM BOX';$('#use-item').disabled=!player.item;
}

function renderMap(){const ctx=mapContext;ctx.clearRect(0,0,220,170);ctx.save();ctx.translate(110,85);ctx.scale(.39,.39);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();trackSamples.forEach((p,i)=>i?ctx.lineTo(p.x,p.z):ctx.moveTo(p.x,p.z));ctx.closePath();ctx.lineWidth=19;ctx.strokeStyle='#91a5a9';ctx.stroke();ctx.lineWidth=12;ctx.strokeStyle='#fff9e6';ctx.stroke();for(const m of projectMeta){ctx.fillStyle='#'+new THREE.Color(m.color).getHexString();ctx.beginPath();ctx.arc(m.position.x,m.position.z,9,0,Math.PI*2);ctx.fill();}for(const r of rivals){ctx.fillStyle='#665c97';ctx.beginPath();ctx.arc(r.kart.position.x,r.kart.position.z,6,0,Math.PI*2);ctx.fill();}ctx.translate(player.x,player.z);ctx.rotate(-player.angle);ctx.beginPath();ctx.moveTo(0,14);ctx.lineTo(-10,-10);ctx.lineTo(10,-10);ctx.closePath();ctx.fillStyle='#ff6b32';ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle='#173650';ctx.stroke();ctx.restore();}
let lastFrame=0,uiFrame=0;
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-lastFrame)/1000,.2)||.016;lastFrame=now;clockTime+=dt;if(now>toastUntil)$('#toast').hidden=true;update(dt,now);
 if(!reduceMotion){itemBoxes.forEach((b,i)=>{b.g.rotation.y=clockTime;b.g.position.y=3.5+Math.sin(clockTime*2+i)*.4;});pickups.forEach(p=>{p.g.rotation.y=clockTime*1.7;p.g.position.y=3.5+Math.sin(clockTime*2+p.index)*.4;});balloons.forEach((b,i)=>b.position.y=70+i*12+Math.sin(clockTime*.4+i)*2);windmills.forEach(b=>b.rotation.z+=dt*.45);}
 if(running){const target=new THREE.Vector3(player.x-Math.sin(player.angle)*22,14+player.y*.65,player.z-Math.cos(player.angle)*22);camera.position.lerp(target,1-Math.exp(-dt*5));const look=new THREE.Vector3(player.x+Math.sin(player.angle)*9,2.5+player.y*.65,player.z+Math.cos(player.angle)*9);camera.lookAt(look);camera.fov=THREE.MathUtils.damp(camera.fov,player.speed>38&&!reduceMotion?63:57,3,dt);}
 else{const mobile=innerWidth<760;const a=reduceMotion?0:Math.sin(clockTime*.075)*.08;const target=new THREE.Vector3(300*Math.cos(a)+100*Math.sin(a),mobile?330:285,420*Math.cos(a)-300*Math.sin(a));camera.position.lerp(target,.035);camera.lookAt(mobile?-45:-85,0,mobile?10:0);camera.fov=mobile?64:48;for(const r of rivals){r.t=(r.t+dt*.012)%1;const p=getPoint(r.t),v=getTangent(r.t);r.kart.position.set(p.x,.94,p.z);r.kart.rotation.y=Math.atan2(v.x,v.z);}}
 for(const sign of worldSigns){if(sign.scale.x<5)continue;sign.getWorldPosition(signPosition);sign.material.opacity=running?THREE.MathUtils.smoothstep(camera.position.distanceTo(signPosition),18,38):1;}
 camera.updateProjectionMatrix();if(gain){gain.gain.setTargetAtTime(soundEnabled&&running&&!paused?.012*musicVolume:0,audioContext.currentTime,.08);oscillator.frequency.setTargetAtTime(45+Math.abs(player.speed)*3,audioContext.currentTime,.08);}if(soundEnabled&&!bgm.paused){const targetVolume=musicVolume*(paused?.32:1);bgm.volume=THREE.MathUtils.damp(bgm.volume,targetVolume,5,dt);}if(++uiFrame%3===0)renderMap();renderer.render(scene,camera);
}
function resize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<760?1.3:1.5));}window.addEventListener('resize',resize);
